const types=['Siembra','Riego','Fertilización','Control de plagas','Inspección','Cosecha'];
const symbols=['✦','≈','＋','◇','✓','▧'];
const certificationNames=['Solicitud','Documentos entregados','Revisión','Inspección','Correcciones','Aprobación final'];
const demo={id:'demo-tomate',code:'TOM-2026-001',producer:'María Fernanda Quispe',location:'Valle de Cochabamba, Bolivia',date:'2026-02-10',activities:[
{type:'Siembra',date:'2026-02-10',description:'Trasplante de tomate variedad Santa Clara en camas preparadas.',input:'Plantines de tomate',dose:'1.200 plantines',observations:'Suelo preparado y separación de 50 cm entre plantas.'},
{type:'Riego',date:'2026-02-17',description:'Primer riego de establecimiento mediante sistema por goteo.',input:'Agua de reservorio',dose:'3.000 L / lote',observations:'Humedad uniforme; sin encharcamiento.'},
{type:'Fertilización',date:'2026-03-03',description:'Aplicación de abono orgánico alrededor de las plantas.',input:'Compost maduro',dose:'250 kg / lote',observations:'Incorporación superficial y riego posterior.'},
{type:'Control de plagas',date:'2026-03-18',description:'Colocación de trampas para monitorear insectos en el cultivo.',input:'Trampas cromáticas amarillas',dose:'12 unidades / lote',observations:'Se observaron pocos insectos; se mantiene el monitoreo.'},
{type:'Inspección',date:'2026-04-15',description:'Revisión del cultivo y de los registros de manejo productivo.',input:'Ficha de inspección',dose:'1 ficha / lote',observations:'Se solicitó completar el registro del origen del compost.'},
{type:'Cosecha',date:'2026-05-12',description:'Cosecha manual de tomates maduros y selección en campo.',input:'Cajas reutilizables',dose:'40 cajas · 800 kg',observations:'Frutos limpios, firmes y sin daños visibles.'}],cert:[
{date:'2026-03-20',description:'Solicitud de certificación de buenas prácticas agrícolas para el lote.'},
{date:'2026-03-23',description:'Ficha del productor, plan de manejo, registro de insumos y croquis del lote.'},
{date:'2026-03-30',description:'Documentación revisada. Se coordinó la visita a la finca.'},
{date:'2026-04-15',description:'Visita de campo. Se solicitó documentar el origen del compost utilizado.'},
{date:'2026-04-20',description:'Comprobante y registro de compost entregados. Observación subsanada.'},
{date:'2026-04-25',description:'Expediente aprobado en esta simulación académica.'}]};
const storageKey='agrorastro-demo-v1';let lots,storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(storageKey));lots=Array.isArray(saved)&&saved.length&&saved.every(l=>l.id&&l.code&&Array.isArray(l.activities)&&Array.isArray(l.cert))?saved:[structuredClone(demo)];}catch{lots=[structuredClone(demo)];storageAvailable=false;}
let selected=lots[0].id,currentView='journey',consumerExpanded=false;
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDate=d=>new Intl.DateTimeFormat('es-BO',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const lot=()=>lots.find(l=>l.id===selected);const sorted=l=>[...l.activities].sort((a,b)=>a.date.localeCompare(b.date));
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(lots));storageAvailable=true;}catch{storageAvailable=false;notify('Cambios guardados solo durante esta sesión.');}}
function meta(label,value){return `<div><span class="meta-label">${label}</span><span class="meta-value">${esc(value)}</span></div>`;}
function info(l){return meta('CÓDIGO DEL LOTE',l.code)+meta('PRODUCTOR',l.producer)+meta('UBICACIÓN',l.location)+meta('FECHA DE REGISTRO',formatDate(l.date));}
function timeline(l){return l.activities.length?`<div class="timeline">${sorted(l).map(a=>`<article class="event"><span class="event-icon" aria-hidden="true">${symbols[types.indexOf(a.type)]||'•'}</span><div><div class="event-title"><h3>${esc(a.type)}</h3><time datetime="${esc(a.date)}">${formatDate(a.date)}</time></div><p>${esc(a.description)}</p><div class="event-detail"><b>Insumo:</b> ${esc(a.input)} &nbsp; · &nbsp; <b>Cantidad / dosis:</b> ${esc(a.dose)}</div><p class="obs"><b>Observaciones:</b> ${esc(a.observations||'Sin observaciones.')}</p></div></article>`).join('')}</div>`:'<p class="empty">Este lote está listo para empezar su recorrido. Registra la primera actividad.</p>';}
function render(){const l=lot();$('#lot-select').innerHTML=lots.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.code)}</option>`).join('');$('.local-note').textContent=storageAvailable?'Guardado en este navegador':'Guardado durante esta sesión';
const harvested=l.activities.some(a=>a.type==='Cosecha');$('#lot-summary').innerHTML=`<section class="lot-card" aria-label="Datos del lote"><div class="lot-top"><div class="crop-icon" aria-hidden="true">✦</div><div class="lot-name"><h2>Tomate · ${esc(l.code)}</h2><p>${l.id===demo.id?'Variedad Santa Clara · Producción de prueba':'Lote de tomate registrado'}</p></div><span class="pill ${harvested?'':'amber'}">${harvested?'Cosecha registrada':'En producción'}</span></div><div class="lot-info">${info(l)}</div></section>`;
document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===currentView);b.setAttribute('aria-current',b.dataset.view===currentView?'page':'false');});
const titles={journey:['Recorrido del lote','Una historia completa, desde la siembra hasta la cosecha.'],cert:['Certificación','Cada etapa del proceso de revisión, en un solo lugar.'],consumer:['Del campo a tu mesa','Conoce quién cultivó tu tomate y cómo llegó hasta aquí.']};$('#page-title').textContent=titles[currentView][0];$('#page-subtitle').textContent=titles[currentView][1];
if(currentView==='journey'){const completed=types.filter(t=>l.activities.some(a=>a.type===t));const days=l.activities.length?Math.round((new Date(sorted(l).at(-1).date)-new Date(sorted(l)[0].date))/86400000):0;$('#view').innerHTML=`<div class="content-grid"><section class="panel"><div class="panel-heading"><h2>Línea de tiempo <span class="count">${l.activities.length} actividades</span></h2><button class="secondary" id="add-activity">＋ Registrar actividad</button></div>${timeline(l)}</section><div class="aside-panels"><section class="panel side-stat"><h3>El ciclo productivo</h3><div class="big-number">${days} <small>días registrados</small></div><p>Entre la primera y la última actividad.</p><div class="progress"><span style="width:${completed.length/6*100}%"></span></div><p>${completed.length} de 6 tipos de actividad registrados</p><div class="stages">${types.map(t=>`<div class="stage"><span>${t}</span><span>${completed.includes(t)?'✓':'Pendiente'}</span></div>`).join('')}</div></section><section class="panel certificate-teaser"><h3>Un origen documentado</h3><p>${l.cert.length===6?'El lote de ejemplo completó todas las etapas de certificación.':'Consulta el estado de los documentos y la revisión de este lote.'}</p><span class="pill ${l.cert.length===6?'':'amber'}">${l.cert.length===6?'Aprobado · Simulación':'Sin aprobación'}</span><button class="secondary" id="go-cert">Ver certificación</button></section></div></div>`;$('#add-activity').onclick=()=>openForm('activity');$('#go-cert').onclick=()=>switchView('cert');}
if(currentView==='cert'){$('#view').innerHTML=`<div class="cert-banner"><span class="cert-symbol" aria-hidden="true">${l.cert.length===6?'✓':'◷'}</span><div><h2>${l.cert.length===6?'Proceso completado':'Certificación pendiente'}</h2><p>${l.cert.length===6?'Buenas prácticas agrícolas · Aprobación de ejemplo':'El nuevo lote aún no tiene un expediente de certificación.'}</p></div></div><section class="panel"><div class="panel-heading"><h2>Etapas de certificación</h2><span class="count">${l.cert.length} de 6 completadas</span></div><ol class="cert-list">${certificationNames.map((name,i)=>`<li class="cert-step ${l.cert[i]?'':'pending'}"><span class="step-number">${i+1}</span><div><h3>${name}</h3><p>${l.cert[i]?esc(l.cert[i].description):'Pendiente de registro.'}</p>${l.cert[i]?`<time datetime="${l.cert[i].date}">${formatDate(l.cert[i].date)}</time>`:''}</div><span class="pill ${l.cert[i]?'':'amber'}">${l.cert[i]?'Completada':'Pendiente'}</span></li>`).join('')}</ol><p class="form-note" style="margin-top:22px">Certificación ficticia para fines académicos. No acredita cumplimiento de una norma.</p></section>`;}
if(currentView==='consumer'){$('#view').innerHTML=`<section class="consumer-card"><div class="consumer-top"><p class="eyebrow">EL ORIGEN DE TU ALIMENTO</p><h2>Tomate con historia.</h2><p>Cultivado por ${esc(l.producer)}<br>en ${esc(l.location)}.</p><span class="pill ${l.cert.length===6?'':'amber'}">${l.cert.length===6?'Certificación aprobada · Demo':'Certificación pendiente'}</span></div><div class="consumer-body"><div class="lot-info">${meta('LOTE',l.code)}${meta('COSECHA',harvested?formatDate(sorted(l).filter(a=>a.type==='Cosecha').at(-1).date):'Aún no registrada')}</div><button class="primary" id="see-trace" aria-expanded="${consumerExpanded}" aria-controls="consumer-trace">${consumerExpanded?'Ocultar trazabilidad':'Ver trazabilidad'}</button><p class="consumer-note">Datos de prueba para una presentación universitaria.</p><div id="consumer-trace" class="consumer-trace" ${consumerExpanded?'':'hidden'}><div class="panel-heading"><h2>Su recorrido productivo</h2></div>${timeline(l)}</div></div></section>`;$('#see-trace').onclick=()=>{consumerExpanded=!consumerExpanded;render();};}}
function switchView(view){currentView=view;render();}document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#lot-select').onchange=e=>{selected=e.target.value;consumerExpanded=false;render();};$('#new-lot').onclick=()=>openForm('lot');$('#close-dialog').onclick=()=>$('#form-dialog').close();
function field(label,name,type='text',value='',required=true){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="180"></div>`;}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function openForm(kind){$('#dialog-title').textContent=kind==='lot'?'Registrar lote de tomate':'Registrar actividad';$('#entry-form').innerHTML=kind==='lot'?`${field('Código del lote','code')}${field('Productor','producer')}${field('Ubicación','location')}${field('Fecha de registro','date','date',today())}<p class="form-note">El nuevo lote comenzará sin actividades ni certificación.</p>`:`<div class="form-row"><div class="field"><label for="field-type">Actividad</label><select id="field-type" name="type">${types.map(t=>`<option>${t}</option>`).join('')}</select></div>${field('Fecha','date','date',today())}</div><div class="field"><label for="field-description">Descripción</label><textarea id="field-description" name="description" required maxlength="1000"></textarea></div><div class="form-row">${field('Insumo usado','input')}${field('Cantidad / dosis','dose')}</div><div class="field"><label for="field-observations">Observaciones (opcional)</label><textarea id="field-observations" name="observations" maxlength="1000"></textarea></div><p class="form-note">Si no usaste un insumo, escribe “Ninguno” y “No aplica”.</p>`;$('#entry-form').insertAdjacentHTML('beforeend','<div class="form-actions"><button class="secondary" type="button" id="cancel-form">Cancelar</button><button class="primary" type="submit">Guardar registro</button></div>');$('#cancel-form').onclick=()=>$('#form-dialog').close();$('#entry-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,v.trim()]));for(const input of e.target.querySelectorAll('[required]')){if(!input.value.trim()){input.setCustomValidity('Completa este campo.');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return;}}if(kind==='lot'){if(lots.some(l=>l.code.toLowerCase()===data.code.toLowerCase())){$('#field-code').setCustomValidity('Este código ya existe. Usa otro código.');$('#field-code').reportValidity();$('#field-code').oninput=()=>$('#field-code').setCustomValidity('');return;}const next={...data,id:crypto.randomUUID(),activities:[],cert:[]};lots.push(next);selected=next.id;currentView='journey';}else{if(data.date<lot().date){$('#field-date').setCustomValidity('La actividad no puede ser anterior al registro del lote.');$('#field-date').reportValidity();$('#field-date').oninput=()=>$('#field-date').setCustomValidity('');return;}lot().activities.push(data);}save();$('#form-dialog').close();render();if(storageAvailable)notify(kind==='lot'?'Lote registrado correctamente.':'Actividad guardada en la línea de tiempo.');};$('#form-dialog').showModal();}
render();
